/**
 * Throwaway. PostgREST serves at "/" and Supabase's kong normally strips the
 * "/rest/v1" prefix. The scratch stack excludes kong, so this restores exactly
 * that one piece of routing and nothing else.
 */
const UPSTREAM = "http://127.0.0.1:57030";

Deno.serve({ port: 57031, hostname: "127.0.0.1" }, async (request) => {
  const url = new URL(request.url);
  if (url.pathname.startsWith("/rest/v1")) {
    url.pathname = url.pathname.slice("/rest/v1".length) || "/";
  }
  const body = request.method === "GET" || request.method === "HEAD" ? undefined : await request.arrayBuffer();
  const upstream = await fetch(new URL(url.pathname + url.search, UPSTREAM), {
    method: request.method,
    headers: request.headers,
    body,
    redirect: "manual",
  });
  return new Response(upstream.body, { status: upstream.status, headers: upstream.headers });
});

